export const solve = xs => {
  const sorted = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1] + sorted[mid]) / 2
    : sorted[mid];
};

export const solve = xs => {
  const groups = new Map();
  for (const { type, n } of xs) {
    if (!groups.has(type)) groups.set(type, []);
    groups.get(type).push(n);
  }
  return Object.fromEntries(groups);
};

export const solve = xs => {
  // Accumulate in a null-prototype object so any `type` value (including
  // "__proto__" or "constructor") is treated as a normal key.
  const groups = Object.create(null);
  for (const { type, n } of xs ?? []) {
    (groups[type] ??= []).push(n); // append in input order
  }
  // Return a plain object; spread preserves the insertion order of keys.
  return { ...groups };
};

