export const solve = xs => {
  const groups = new Map();
  for (const { type, n } of xs) {
    if (!groups.has(type)) groups.set(type, []);
    groups.get(type).push(n);
  }
  const out = {};
  // defineProperty 避免 type 为 "__proto__" 等特殊键时污染/丢失分组
  for (const [type, ns] of groups) {
    Object.defineProperty(out, type, {
      value: ns,
      enumerable: true,
      writable: true,
      configurable: true,
    });
  }
  return out;
};

