export const solve = xs => {
  const sorted = [...xs].sort((a, b) => a - b);
  const n = sorted.length;
  const mid = n >> 1;
  if (n % 2 !== 0) return sorted[mid];
  const a = sorted[mid - 1];
  const b = sorted[mid];
  return a + (b - a) / 2;
};

